import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { AuthService } from '../service/auth/auth.service';
import { HttpClient } from '@angular/common/http';
import * as bcrypt from 'bcryptjs';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css'],
})
export class LoginComponent {
  formData = {
    username: '',
    password: '',
  };

  error: string = '';

  constructor(
    private authService: AuthService,
    private router: Router,
    private http: HttpClient
  ) {}

  // onSubmit() {
  //   this.error = '';
  //   this.authService.authenticate(
  //     this.formData,
  //     () => {
  //       console.log('Redirecting to home...');
  //       this.router.navigate(['/home']);
  //     },
  //     (error) => {
  //       if (this.formData.username == '') this.error = 'Username is required!';
  //       else if (this.formData.password == '')
  //         this.error = 'Password is required!';
  //       else this.error = error.error.message;
  //     }
  //   );
  // }

  onSubmit() {
    this.error = '';

    // this.formData.password = bcrypt.hashSync(this.formData.password, 10);
    this.authService.authenticate(
      this.formData,
      () => {
        console.log('Redirecting to home...');
        this.router.navigate(['/home']);
      },
      (error) => {
        if (this.formData.username == '') this.error = 'Username is required!';
        else if (this.formData.password == '')
          this.error = 'Password is required!';
        else this.error = error.error.message;
      }
    );
  }

  showError(error: string): string {
    this.error = error;
    return error;
  }
}
<div id="login-container">
  <div class="background"></div>
  <div class="login-container">
    <form (ngSubmit)="onSubmit()">
      <div class="form-group">
        <label for="username">Username:</label>
        <input
          type="text"
          id="username"
          name="username"
          minlength="5"
          maxlength="15"
          [(ngModel)]="formData.username"
          required
        />
      </div>
      <div class="form-group">
        <label for="password">Password:</label>
        <input
          type="password"
          id="password"
          name="password"
          [(ngModel)]="formData.password"
          required
          minlength="5"
          maxlength="15"
        />
      </div>
      <div *ngIf="error" class="errorLabel">{{ error }}</div>
      <div></div>
      <button class="button" type="submit">Login</button>
      <div>
        <a class="register" href="/register"> Don't have an account? </a>
      </div>
    </form>
  </div>
</div>
<footer>
  <p>&copy; 2023 Project Aurora. All rights reserved.</p>
</footer>
